import{_ as a,o,c as d,a5 as c}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 28 话 CSS 嵌套：规则套规则","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.28-css-nesting.md","filePath":"comics/css/EP.28-css-nesting.md","lastUpdated":1793421609000}'),s={name:"comics/css/EP.28-css-nesting.md"};function r(t,e,i,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-28-话-css-嵌套-规则套规则" tabindex="-1">漫画 · 第 28 话 CSS 嵌套：规则套规则 <a class="header-anchor" href="#漫画-·-第-28-话-css-嵌套-规则套规则" aria-label="Permalink to &quot;漫画 · 第 28 话 CSS 嵌套：规则套规则&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/18-css-nesting">docs/css/18-css-nesting.md</a> ｜ 原画：<a href="./EP.28-css-nesting.svg">EP.28-css-nesting.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。维护一套扁平 CSS，<code>.card</code> 相关的规则散落在文件各处，改个类名要全局搜索替换；想引入 Sass 又要拉起一整套工具链。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 CSS Nesting 标准——子规则直接写进父规则，<code>&amp;</code> 引用父选择器，浏览器解析期自动展开，与手写完全等价。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>层叠层章（EP.23）解决了「优先级管理」，本话解决「书写结构」。像素酱被扁平 CSS 的重复与散落折磨，标签君引入原生嵌套：<code>&amp;:hover</code> 同元素状态、<code>&amp;.featured</code> 同元素变体、<code>.card &amp;</code> 祖先条件、<code>@media</code> 嵌套断点——Sass 用户几乎零学习成本，且不需要任何构建工具。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>扁平 CSS 里同一个组件的规则被拆成多条：<code>.card</code>、<code>.card .title</code>、<code>.card .title:hover</code>、<code>.card.featured</code>……父选择器重复书写，组件样式散落几十行。引入预处理器能解决问题，但要付出工具链成本：编译、source map、额外依赖。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>CSS Nesting 是解析期语法糖：浏览器把嵌套规则展开成等价长形式再进入层叠。核心是 <code>&amp;</code> 嵌套选择器——引用父规则匹配的元素。<code>&amp;:hover</code>（无空格）= 同元素加伪类；<code>.featured</code>（有空格）= 后代元素。<code>&amp;</code> 还能出现在任意位置：<code>.card &amp;</code> 展开为 <code>.card .title</code>，实现祖先条件反向书写。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：按钮全状态收拢（<code>&amp;:hover</code>/<code>&amp;:disabled</code>/<code>&amp;.primary:hover</code> 全在一个块内）、响应式跟着组件走（<code>@media</code> 嵌套在 <code>.sidebar</code> 内部）、祖先条件反向写（<code>[data-theme=dark] &amp;</code> 驱动主题）、嵌套 + <code>:has()</code> 组合拳（零 JS 表单验证提示）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>&amp;.featured 是同元素状态，.featured 是后代元素——一字之差语义不同。</li><li>嵌套深度 ≤ 3 层，别把 HTML 结构硬编码进选择器。</li><li>@media 直接嵌套在组件内部，响应式不再跳转文件底部。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>.card { &amp;.featured { } }</code> 和 <code>.card { .featured { } }</code> 展开后分别是什么？匹配的元素有何不同？</p><p><strong>答</strong>：前者展开为 <code>.card.featured</code>——匹配<strong>同时</strong>带有 card 和 featured 两个类的<strong>同一个</strong>元素（空格都没有）；后者展开为 <code>.card .featured</code>——匹配 <code>.card</code> 元素<strong>后代中</strong>带 featured 类的元素。少写一个 <code>&amp;</code>，选择器从「状态变体」变成「后代查找」，静默失效不报错，是嵌套迁移时最高发的错误。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>基础嵌套 + <code>&amp;</code> 父引用 + 嵌套 @media + 主题切换 + 嵌套:has() 表单：<a href="./../../examples/css/18-css-nesting/index-01-css-nesting.html">examples/css/18-css-nesting/</a></li></ul><h2 id="系列结语" tabindex="-1">系列结语 <a class="header-anchor" href="#系列结语" aria-label="Permalink to &quot;系列结语&quot;">​</a></h2><p>至此「霓虹墨」漫画剧场 CSS 篇扩展完结（EP.22–28）：容器查询、层叠层、现代颜色、滚动驱动动画、:has()、View Transitions、CSS 嵌套——现代 CSS 的七件新装备全部到手。</p>',22)])])}const u=a(s,[["render",r]]);export{p as __pageData,u as default};
